53		st, err := s.Status("u")
54		if err != nil {
55			t.Fatal(err)
56		}
57		if st.CurrentTerms.PlanID != "a" || st.PendingChange == nil || *st.PendingChange != wantChange {
58			t.Fatalf("status after schedule: cur=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
59		}
60	
61		// 修改套餐定义后，同一目标的重复安排返回原安排，不重新取价。
62		if err := s.UpdatePlan(planDef("b", 9999, 1, 99, 2000)); err != nil {
63			t.Fatal(err)
64		}
65		r2 := mustSchedule(t, s, "u", "b")
66		if r2.Created || r2.Change != wantChange {
67			t.Fatalf("same target replay: created=%v change=%+v", r2.Created, r2.Change)
68		}
69	
70		// 换一个目标：替换原安排，生效月份仍是本次接受时的下一月（仍为 2 月）。
71		r3 := mustSchedule(t, s, "u", "c")
72		if !r3.Created || r3.Change.TargetPlanID != "c" || r3.Change.EffectivePeriod != feb(2026) {
73			t.Fatalf("replace schedule: %+v", r3)
74		}
75		if r3.Change.Terms != termsOf(planDef("c", 3000, 30, 9, 0)) {
76			t.Fatalf("replacement terms: %+v", r3.Change.Terms)
77		}
78		st, _ = s.Status("u")
79		if st.PendingChange == nil || st.PendingChange.TargetPlanID != "c" {
80			t.Fatalf("pending after replace: %+v", st.PendingChange)
81		}
82	
83		// 月末深夜安排，生效月仍是次月；恰在月初零点，新安排从再下一月生效。
84		clk.t = utc(2026, 1, 31, 23, 59)
85		mustAccount(t, s, "v")
86		mustSubscribe(t, s, "v", "a", utc(2026, 1, 1, 0, 0))
87		rv := mustSchedule(t, s, "v", "b")
88		if rv.Change.EffectivePeriod != feb(2026) {
89			t.Fatalf("late Jan schedule effective = %v", rv.Change.EffectivePeriod)
90		}
91		clk.t = utc(2026, 2, 1, 0, 0)
92		// 此刻 v 的 b 安排已生效；为 c 安排应从 3 月生效。
93		rc := mustSchedule(t, s, "v", "c")
94		if rc.Change.EffectivePeriod != mar(2026) {
95			t.Fatalf("schedule exactly at boundary effective = %v, want 2026-03", rc.Change.EffectivePeriod)
96		}
97	}
