123			t.Fatalf("not activated: %v", err)
124		}
125		if _, err := s.SchedulePlanChange("u", "ghost"); !errors.Is(err, ErrPlanNotFound) {
126			t.Fatalf("missing plan: %v", err)
127		}
128		if _, err := s.SchedulePlanChange("u", "a"); !errors.Is(err, ErrPlanChangeSamePlan) {
