213			t.Fatalf("saved pre-effect result changed = %+v, want %+v", before.PendingChange, wantPending)
214		}
215	
216		// 后续查询不能反过来改变旧结果。
217		if _, err := s.Status("u"); err != nil {
218			t.Fatal(err)
219		}
220		if before.PendingChange == nil || *before.PendingChange != wantPending {
221			t.Fatalf("saved pre-effect result changed by later query = %+v, want %+v", before.PendingChange, wantPending)
222		}
223		if before.CurrentTerms != termsA {
224			t.Fatalf("saved pre-effect current changed = %+v, want %+v", before.CurrentTerms, termsA)
225		}
226	}
